import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"废弃接口","link":"/api/SIMD-API/c_api/deprecated_interface/deprecated_interface"},{"text":"asc_half2int32（废弃）","link":"/api/SIMD-API/c_api/deprecated_interface/asc_half2int32_deprecated"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/deprecated_interface/asc_half2int32_deprecated.md","filePath":"api/SIMD-API/c_api/deprecated_interface/asc_half2int32_deprecated.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":3,"title":"迁移说明","slug":"迁移说明","link":"#迁移说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":3,"title":"模板原型（占位符形式）","slug":"模板原型（占位符形式）","link":"#模板原型（占位符形式）"},{"level":3,"title":"占位符说明","slug":"占位符说明","link":"#占位符说明"},{"level":3,"title":"函数原型典型示例","slug":"函数原型典型示例","link":"#函数原型典型示例"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788243127000}'),l={name:"api/SIMD-API/c_api/deprecated_interface/asc_half2int32_deprecated.md"};function e(t,s,d,i,o,r){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>asc_half2int32（废弃）</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><strong>该接口通过接口后缀来控制源操作数读取位置（仅包括源操作数、目的操作数、掩码寄存器三个参数）的原型已废弃，请使用<a href="../reg_compute/reg_convert/asc_half2int32.html">asc_half2int32</a>的显式位置参数重载替代。</strong></p><p>根据<code>mask</code>将<code>src</code>中的每个参与计算的<code>half</code>类型元素转换为<code>int32_t</code>类型，结果写入<code>dst</code>。由于源操作数与目的操作数类型位宽比为1:2，读取数据时需要将一个<code>VL</code>大小的数据分为两部分，根据接口后缀选择读取<code>src</code>索引为偶数的位置或奇数的位置。伪代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">def</span><span class="w"> </span><span class="nf">asc_half2int32_rd</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span> <span class="n">src</span><span class="p">,</span> <span class="n">mask</span><span class="p">):</span>
    <span class="k">for</span> <span class="n">i</span> <span class="ow">in</span> <span class="nb">range</span><span class="p">(</span><span class="mi">64</span><span class="p">):</span>
        <span class="k">if</span> <span class="n">mask</span><span class="p">[</span><span class="mi">2</span> <span class="o">*</span> <span class="n">i</span><span class="p">]:</span>
            <span class="n">dst</span><span class="p">[</span><span class="n">i</span><span class="p">]</span> <span class="o">=</span> <span class="n">int32</span><span class="p">(</span><span class="n">src</span><span class="p">[</span><span class="mi">2</span> <span class="o">*</span> <span class="n">i</span><span class="p">])</span>   <span class="c1"># half -&gt; int32，FLOOR舍入，读取偶数索引</span>
        <span class="k">else</span><span class="p">:</span>
            <span class="n">dst</span><span class="p">[</span><span class="n">i</span><span class="p">]</span> <span class="o">=</span> <span class="mi">0</span>

<span class="k">def</span><span class="w"> </span><span class="nf">asc_half2int32_rd_v2</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span> <span class="n">src</span><span class="p">,</span> <span class="n">mask</span><span class="p">):</span>
    <span class="k">for</span> <span class="n">i</span> <span class="ow">in</span> <span class="nb">range</span><span class="p">(</span><span class="mi">64</span><span class="p">):</span>
        <span class="k">if</span> <span class="n">mask</span><span class="p">[</span><span class="mi">2</span> <span class="o">*</span> <span class="n">i</span> <span class="o">+</span> <span class="mi">1</span><span class="p">]:</span>
            <span class="n">dst</span><span class="p">[</span><span class="n">i</span><span class="p">]</span> <span class="o">=</span> <span class="n">int32</span><span class="p">(</span><span class="n">src</span><span class="p">[</span><span class="mi">2</span> <span class="o">*</span> <span class="n">i</span> <span class="o">+</span> <span class="mi">1</span><span class="p">])</span>  <span class="c1"># half -&gt; int32，FLOOR舍入，读取奇数索引</span>
        <span class="k">else</span><span class="p">:</span>
            <span class="n">dst</span><span class="p">[</span><span class="n">i</span><span class="p">]</span> <span class="o">=</span> <span class="mi">0</span>
</code></pre></div><p>关于舍入模式的详细说明，请参见<a href="../reg_compute/reg_convert/rounding_mode.html">舍入模式</a>。</p><h3 id="迁移说明">迁移说明<a class="header-anchor" href="#迁移说明">​</a></h3><p><strong>表1</strong> 新旧位置参数对应关系</p><table><thead><tr><th>旧原型位置后缀</th><th>新原型位置参数</th></tr></thead><tbody><tr><td>无位置后缀</td><td><code>ASC_POSITION_EVEN</code></td></tr><tr><td><code>_v2</code></td><td><code>ASC_POSITION_ODD</code></td></tr></tbody></table><p>迁移时移除函数名中的位置后缀，并将对应位置常量作为第四个参数传入。新原型请参见<a href="../reg_compute/reg_convert/asc_half2int32.html">asc_half2int32</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><h3 id="模板原型（占位符形式）">模板原型（占位符形式）<a class="header-anchor" href="#模板原型（占位符形式）">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_half2int32_</span><span class="o">&lt;</span><span class="n">round_mode</span><span class="o">&gt;&lt;</span><span class="n">position_mode</span><span class="o">&gt;</span><span class="p">(</span><span class="n">vector_int32_t</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                                       </span><span class="n">vector_half</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                                       </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">)</span>
</code></pre></div><h3 id="占位符说明">占位符说明<a class="header-anchor" href="#占位符说明">​</a></h3><ul><li><code>&lt;round_mode&gt;</code>表示支持的舍入模式，支持<code>rd</code>（<code>FLOOR</code>）、<code>rn</code>（<code>RINT</code>）、<code>rna</code>（<code>ROUND</code>）、<code>ru</code>（<code>CEIL</code>）和<code>rz</code>（<code>TRUNC</code>）。</li><li><code>&lt;position_mode&gt;</code>表示<code>src</code>读取的位置，为空时，结果读取<code>src</code>的偶数索引位置；取值为<code>_v2</code>时，结果读取<code>src</code>的奇数索引位置。</li></ul><h3 id="函数原型典型示例">函数原型典型示例<a class="header-anchor" href="#函数原型典型示例">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// FLOOR舍入模式，读取src索引为偶数的位置</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_half2int32_rd</span><span class="p">(</span><span class="n">vector_int32_t</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                              </span><span class="n">vector_half</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                              </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数（矢量数据寄存器）。</td></tr><tr><td>src</td><td>输入</td><td>源操作数（矢量数据寄存器）。</td></tr><tr><td>mask</td><td>输入</td><td>掩码寄存器，用于控制各元素是否参与计算。<code>mask</code>中与元素对应的比特位为1时，该元素参与计算；为0时，该元素不参与计算。</td></tr></tbody></table><p>矢量数据寄存器和掩码寄存器的详细说明请参见<a href="../defs/type/data_type_definition.html">reg数据类型定义</a>。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>通过引用参数输出结果的函数原型在非AIV上调用时直接返回。</li><li>本接口在Vector Function（<code>__simd_vf__</code>标记的函数）内调用。</li><li><code>mask</code>需通过掩码设置接口预先赋值后再传入，未赋值的掩码寄存器内容不确定，会导致有效元素位置错误。</li><li><code>mask</code>掩码位为0时，<code>dst</code>对应元素置0。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">dst</span><span class="p">;</span>
<span class="n">vector_half</span><span class="w"> </span><span class="n">src</span><span class="p">;</span>
<span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b16</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="n">asc_half2int32_rd</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span><span class="w">     </span><span class="c1">// FLOOR舍入模式，读取src索引为偶数的位置</span>
<span class="n">asc_half2int32_rd_v2</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span><span class="w">  </span><span class="c1">// FLOOR舍入模式，读取src索引为奇数的位置</span>
</code></pre></div></article></div>`,1)])])}const v=a(l,[["render",e]]);export{_ as __pageData,v as default};
